    ($q$D.5.7$q$, $q$Did the company conduct an annual performance assessment of the board committees and disclose the criteria and process followed for the assessment Apakah perusahaan melakukan penilaian kinerja tahunan komite di bawah Direksi dan Dewan Komisaris serta mengungkapkan kriteria dan proses penilaian$q$, $q$ Perusahaan telah melakukan penilaian kinerja tahunan komite di bawah Direksi dan Dewan Komisaris serta telah m e n gungkapkan kriteria dan proses penilaiannya.$q$, $q$1) Laporan Tahunan Perusahaan 2024 hal. 332 dan 357 2) https://www.pln.co.id/ hubungan-investor- id/publikasi-investor- id/laporan-tahunan-id$q$, $q$yes$q$, $q$$q$)
)
update public.acgs_assessments as a
set
  question_id = coalesce(nullif(a.question_id, ''), source.standar_tata_kelola),
  implementation = source.implementation,
  evidence = source.evidence,
  status = nullif(source.status, ''),
  recommendation = source.recommendation,
  updated_at = now()
from source
where a.year = 2025
  and a.item_id = source.item_id;

commit;

