    ($q$(B)B.1.7$q$, $q$LEVEL 2 (BONUS ITEMS)$q$, $q$B$q$, $q$(B)B.1.7$q$, $q$Whistle Blowing System Perusahaan dikelola oleh pihak/institusi independen.$q$, $q$$q$, $q$Whistle Blowing System Perusahaan dikelola oleh pihak/institusi independen.$q$, $q$$q$),
    ($q$(B)C.1.1$q$, $q$LEVEL 2 (BONUS ITEMS)$q$, $q$C$q$, $q$(B)C.1.1$q$, $q$Perusahaan merilis atau menerbitkan Laporan Keuangan Tahunan Audited dalam waktu 60 hari sejak tahun buku berakhir.$q$, $q$$q$, $q$Perusahaan merilis atau menerbitkan Laporan Keuangan Tahunan Audited dalam waktu 60 hari sejak tahun buku berakhir.$q$, $q$$q$),
    ($q$(B)D.1.1$q$, $q$LEVEL 2 (BONUS ITEMS)$q$, $q$D$q$, $q$(B)D.1.1$q$, $q$Perusahaan memiliki setidaknya satu orang Komisaris Independen dari unsur gender perempuan.$q$, $q$$q$, $q$Perusahaan memiliki setidaknya satu orang Komisaris Independen dari unsur gender perempuan.$q$, $q$$q$),
    ($q$(B)D.1.2$q$, $q$LEVEL 2 (BONUS ITEMS)$q$, $q$D$q$, $q$(B)D.1.2$q$, $q$Perusahaan menyusun kebijakan dan mengungkapkan indikator tujuan atas implementasi keberagaman Direksi dan Dewan Komisaris termasuk laporan perkembangan atas pencapaian tujuan tersebut (Pada Laporan Tahunan yang dipublikasikan dalam website Perusahaan).$q$, $q$$q$, $q$Perusahaan menyusun kebijakan dan mengungkapkan indikator tujuan atas implementasi keberagaman Direksi dan Dewan Komisaris termasuk laporan perkembangan atas pencapaian tujuan tersebut (Pada Laporan Tahunan yang dipublikasikan dalam website Perusahaan).$q$, $q$$q$),
    ($q$(B)D.2.2$q$, $q$LEVEL 2 (BONUS ITEMS)$q$, $q$D$q$, $q$(B)D.2.2$q$, $q$Komite Nominasi melakukan proses identifikasi kandidat Direktur sejalan dengan arahan strategi Perusahaan.$q$, $q$$q$, $q$Komite Nominasi melakukan proses identifikasi kandidat Direktur sejalan dengan arahan strategi Perusahaan.$q$, $q$$q$),
    ($q$(B)D.4.1$q$, $q$LEVEL 2 (BONUS ITEMS)$q$, $q$D$q$, $q$(B)D.4.1$q$, $q$Komposisi Komisaris Independen lebih dari 50% dari jumlah keseluruhan anggota Dewan Komisaris.$q$, $q$$q$, $q$Komposisi Komisaris Independen lebih dari 50% dari jumlah keseluruhan anggota Dewan Komisaris.$q$, $q$$q$)
), updated as (
  update public.aoi_items as a
  set
    level_label = source.level_label,
    part_id = source.part_id,
    section_id = source.section_id,
    standar_label = source.standar_label,
    fakta_temuan = source.fakta_temuan,
    rekomendasi = source.rekomendasi,
    eviden = source.eviden,
    updated_at = now()
  from source
  where a.year = 2025
    and a.section_id = source.section_id
  returning source.item_id
)
insert into public.aoi_items (
  year, sort_order, level_label, part_id, section_id, standar_label,
  fakta_temuan, rekomendasi, pic, status_rekomendasi, eviden
)
select
  2025,
  row_number() over (order by source.item_id),
  source.level_label,
  source.part_id,
  source.section_id,
  source.standar_label,
  source.fakta_temuan,
  source.rekomendasi,
  '',
  'Belum ditindak-lanjuti',
  source.eviden
from source
where not exists (
  select 1 from updated where updated.item_id = source.item_id
);

commit;

-- Verifikasi AOI tahun 2025:
select section_id, rekomendasi
from public.aoi_items
where year = 2025
  and section_id in (
    $q$A.2.8$q$, $q$A.2.10$q$, $q$A.2.11$q$, $q$A.2.12$q$, $q$A.2.13$q$, $q$A.2.14$q$, $q$A.6.4$q$, $q$A.6.5$q$, $q$A.8.3$q$, $q$B.6.3$q$, $q$C.3.2$q$, $q$C.3.3$q$, $q$C.3.4$q$, $q$C.8.1$q$, $q$C.8.2$q$, $q$C.9.1$q$, $q$C.9.6$q$, $q$D.3.3$q$, $q$D.3.4$q$, $q$D.3.6$q$, $q$D.3.13$q$, $q$D.3.16$q$, $q$D.5.6$q$, $q$(B)A.1.1$q$, $q$(B)B.1.6$q$, $q$(B)B.1.7$q$, $q$(B)C.1.1$q$, $q$(B)D.1.1$q$, $q$(B)D.1.2$q$, $q$(B)D.2.2$q$, $q$(B)D.4.1$q$
  )
order by sort_order nulls last, section_id;
